import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        skip();
        int st = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        int len = pos - st;
        // positions[c][r-1]: 1-based position of the r-th occurrence of digit c.
        int[] total = new int[10];
        for (int i = 0; i < len; i++) total[buf[st + i] - '0']++;
        int[][] positions = new int[10][];
        for (int c = 0; c < 10; c++) positions[c] = new int[total[c]];
        int[] fill = new int[10];
        for (int i = 0; i < len; i++) {
            int c = buf[st + i] - '0';
            positions[c][fill[c]++] = i + 1;
        }
        int q = nextInt();
        StringBuilder sb = new StringBuilder();
        sb.append(q).append('\n');
        int[] cnt = new int[10];
        for (int j = 0; j < q; j++) {
            int length = nextInt();
            skip();
            int a = pos;
            while (pos < buf.length && buf[pos] > ' ') pos++;
            java.util.Arrays.fill(cnt, 0);
            if (length > 0)
                for (int k = a; k < pos; k++) cnt[buf[k] - '0']++;
            int answer = 0;
            for (int c = 0; c < 10 && answer >= 0; c++) {
                if (cnt[c] == 0) continue;
                if (positions[c].length < cnt[c]) answer = -1;
                else answer = Math.max(answer, positions[c][cnt[c] - 1]);
            }
            if (j > 0) sb.append(' ');
            sb.append(answer);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := next()
	// positions[c][r-1]: 1-based position of the r-th occurrence of digit c.
	var positions [10][]int
	for i, c := range s {
		positions[c-'0'] = append(positions[c-'0'], i+1)
	}
	q := int(nextInt())
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(q) + "\n")
	for j := 0; j < q; j++ {
		length := nextInt()
		query := next()
		var cnt [10]int
		if length > 0 {
			for _, c := range query {
				cnt[c-'0']++
			}
		}
		answer := 0
		for c := 0; c < 10 && answer >= 0; c++ {
			if cnt[c] == 0 {
				continue
			}
			if len(positions[c]) < cnt[c] {
				answer = -1
			} else {
				answer = max(answer, positions[c][cnt[c]-1])
			}
		}
		if j > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(answer))
	}
	w.WriteByte('\n')
}
